    "database_url", "connection_string", "conn_string",
    "sha512_password", "sha256_password", "md5_password",
    "no_password", "root_password", "admin_password"
}

is_credential_field_name(name) {
    lower_name := lower(name)
    pattern := credential_field_patterns[_]
    lower_name == pattern
}

is_credential_field_name(name) {
    lower_name := lower(name)
    pattern := credential_field_patterns[_]
    endswith(lower_name, concat("", ["_", pattern]))
}

is_credential_field_name(name) {
    lower_name := lower(name)
    pattern := credential_field_patterns[_]
    startswith(lower_name, concat("", [pattern, "_"]))
}

is_credential_field_name(name) {
