is_hardcoded_string(node) {
    node.ir_type == "String"
    count(node.value) > 0
}

is_secure_reference(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
}

is_secure_reference(node) {
    walk(node, [_, n])
    n.ir_type == "FunctionCall"
    regex.match("^(vault_|data\\.|var\\.)", n.name)
}

get_all_hash_kv_pairs(node) = kv_pairs {
    kv_pairs := {kv |
        walk(node, [_, current])
        current.ir_type == "Hash"
        kv := current.value[_]
        kv[0].ir_type == "String"
    }
}

get_all_array_elements(node) = elements {
    elements := {elem |
        walk(node, [_, current])
        current.ir_type == "Array"
        elem := current.value[_]
    }
}

check_hardcoded_hash_entry(node, path, parent_element) = result {
    kv_pairs := get_all_hash_kv_pairs(node)
    count(kv_pairs) > 0
    kv := kv_pairs[_]
    is_credential_field_name(kv[0].value)
